  if(remote){state=remote;state.settings.auth=state.settings.auth||{googleClientId:'',requireGoogleLogin:false};await saveLocalState(state);await saveCloudWorkspaceState(state)}
  else if(member.role==='SUPER_ADMIN'){await saveCloudWorkspaceState(state);toast('Cloud workspace created from this device.')}
