function syncEmployeeRates(){const f=el('employee-form');if(!f)return;const basis=f.elements.payrollType.value,monthly=Number(f.elements.monthlyBasic.value||0),divisor=Number(f.elements.monthlyDivisor.value||0),hours=Number(f.elements.normalHours.value||0);const auto=basis==='Monthly';for(const name of ['dailyRate','hourlyRate','weeklyRate']){f.elements[name].readOnly=auto;f.elements[name].closest('.field')?.classList.toggle('auto-field',auto)}if(auto&&monthly>0&&divisor>0&&hours>0){const daily=monthly*12/divisor,hourly=daily/hours,weekly=monthly*12/52;f.elements.dailyRate.value=daily.toFixed(2);f.elements.hourlyRate.value=hourly.toFixed(2);f.elements.weeklyRate.value=weekly.toFixed(2);const preview=el('rate-preview');if(preview)preview.textContent=`Daily ₱${daily.toLocaleString('en-PH',{minimumFractionDigits:2,maximumFractionDigits:2})} · Hourly ₱${hourly.toLocaleString('en-PH',{minimumFractionDigits:2,maximumFractionDigits:2})} · Weekly ₱${weekly.toLocaleString('en-PH',{minimumFractionDigits:2,maximumFractionDigits:2})}`}}
