function statusForm(id){editingId=id;const e=state.employees.find(e=>e.id===id);modal('Change employee status',`<div class="callout info">Payroll eligibility follows effective dates. Deactivation preserves all attendance, contribution, and payroll history.</div>`+form('status-form',select('New status','status',statuses,statusOn(e,today())==='ACTIVE'?'INACTIVE':'ACTIVE')+field('Effective date','date',today(),'date')+note('Reason','reason','',true),'Record status change'))}
function attendanceForm(id){editingId=id||null;const a=state.attendance.find(a=>a.id===id)||{employeeId:state.employees.find(e=>activeOn(e,filters.attendanceDate||today()))?.id,date:filters.attendanceDate||'2026-09-18',status:'Present',timeIn:'09:00',timeOut:'18:00',breakStart:'12:00',breakMinutes:60,otApproved:true,holidayEligible:false};modal(id?'Correct attendance':'Add attendance',form('attendance-form',select('Employee','employeeId',empOptions(),a.employeeId,true)+field('Work date','date',a.date,'date')+select('Status','status',attendanceStatuses,a.status)+field('Clock in','timeIn',a.timeIn,'time',{required:false})+field('Clock out','timeOut',a.timeOut,'time',{required:false})+field('Break starts','breakStart',a.breakStart,'time',{required:false})+field('Break duration (minutes)','breakMinutes',a.breakMinutes,'number',{min:0,max:240,step:1})+check('Clock out is on the next day','overnight',a.overnight)+check('Overtime reviewed / approved','otApproved',a.otApproved)+`<div class="field wide">${check('Eligible for unworked regular holiday pay','holidayEligible',a.holidayEligible)}<small>Confirm applicable coverage and preceding-day attendance/leave requirements.</small></div>`+note('Audit note / correction reason','note',a.note,id?true:false),id?'Save correction':'Add attendance'))}
function customAttendanceForm(){const base=filters.attendanceDate||today();modal('Generate custom-date attendance',`<div class="callout info"><strong>Batch attendance generator</strong><div>Create daily time records for a custom date range. Existing employee/date records are skipped so nothing is overwritten.</div></div>`+form('custom-attendance-form',select('Employees','employeeScope',[['all','All active employees'],...empOptions()],'all',true)+field('From date','from',base,'date')+field('To date','to',base,'date')+select('Attendance status','status',attendanceStatuses,'Present')+field('Clock in','timeIn','09:00','time',{required:false})+field('Clock out','timeOut','18:00','time',{required:false})+field('Break starts','breakStart','12:00','time',{required:false})+field('Break duration (minutes)','breakMinutes',60,'number',{min:0,max:240,step:1})+`<div class="field wide generator-options">${check('Skip each employee’s rest days','skipRestDays',true)}${check('Mark overtime as reviewed / approved','otApproved',true)}${check('Eligible for unworked regular holiday pay','holidayEligible',false)}</div>`+note('Batch note / reference','note','Generated from custom date attendance tool',false),'Generate attendance'))}

function newPayroll(){const last=[...state.payrolls].filter(p=>p.kind==='Regular'&&p.status!=='Voided').sort((a,b)=>a.period.to.localeCompare(b.period.to)).at(-1);const from=last?addDays(last.period.to,1):addDays(today(),-6),to=addDays(from,6);modal('Run payroll',`<div class="callout info">Attendance, effective employee status, holidays, and saved rule versions determine the calculation. Review validation before approval.</div>`+form('payroll-form',field('Period from','from',from,'date')+field('Period to','to',to,'date')+field('Pay date','payDate',to,'date')+select('Withholding frequency','frequency',[['daily','Daily'],['weekly','Weekly'],['semiMonthly','Semi-monthly'],['monthly','Monthly']],state.settings.frequency),'Generate payroll').replace('<button class="btn primary" type="submit">', '<button class="btn" type="submit" name="saveDraft" value="yes">Save draft</button><button class="btn primary" type="submit">'))}
function viewPayroll(id){const p=state.payrolls.find(p=>p.id===id);const t=totals(p.lines),v=validatePayroll(state,p),final=['Approved','Paid','Voided'].includes(p.status);const next={Draft:'Calculated',Calculated:'Reviewed',Reviewed:'Approved',Approved:'Paid'}[p.status];modal(p.number,`<div class="row between mb"><span>${tag(p.status)} <span class="muted" style="font-size:.8rem">${esc(p.kind)}</span></span><span style="font-size:.8rem">${dateLabel(p.period.from)} – ${dateLabel(p.period.to)} · Pay ${dateLabel(p.payDate)}</span></div><div class="inline-stats"><div><label>Gross pay</label><strong>${money(t.gross)}</strong></div><div><label>Deductions</label><strong>${money(t.totalDeductions)}</strong></div><div><label>Net payroll</label><strong>${money(t.net)}</strong></div></div>${!final?`<div class="callout ${v.errors.length?'error':'info'}"><strong>Payroll validation · ${v.errors.length} critical errors · ${v.warnings.length} warnings</strong>${v.errors.slice(0,12).map(e=>`<div>${esc(e)}</div>`).join('')}${v.errors.length>12?`<div>+ ${v.errors.length-12} additional errors</div>`:''}${!v.errors.length?'<div>Required checks passed. Review calculations and warnings below.</div>':''}</div>`:''}<details class="mb"><summary style="font-size:.8rem;cursor:pointer">Validation notes & statutory rules</summary><p class="muted mt">${v.warnings.map(esc).join('<br>')||'No warnings.'}</p><p class="mt" style="font-size:.74rem">${p.ruleSnapshots.map(r=>`${esc(r.version)} · ${esc(r.effectiveFrom)}`).join('<br>')}</p></details>${table(['EMPLOYEE','GROSS','DEDUCTIONS','NET PAY',''],p.lines.map(l=>`<tr><td><span class="table-main">${esc(l.name)}</span><small class="sub">${esc(l.employee.code)}</small></td><td>${money(l.gross)}</td><td>${money(l.totalDeductions)}</td><td class="table-main">${money(l.net)}</td><td>${btn('View computation','computation','link',`data-id="${p.id}" data-employee="${l.employeeId}"`)}</td></tr>`))}<div class="form-actions" style="flex-wrap:wrap;justify-content:flex-start">${btn('Payslips','all-payslips','',dataAttrs(id))}${!final?btn('Recalculate','recalculate','',dataAttrs(id)):''}${p.status!=='Paid'&&p.status!=='Voided'?btn('Void','void-payroll','danger',dataAttrs(id)):''}${next?btn(next==='Calculated'?'Calculate draft':next==='Reviewed'?'Mark reviewed':next==='Approved'?'Approve payroll':'Mark as paid','transition','primary',dataAttrs(id)+` data-next="${next}" ${v.errors.length&&!final?'disabled':''}`):''}</div>`)}
function computation(id,employee){const p=state.payrolls.find(x=>x.id===id),l=p.lines.find(x=>x.employeeId===employee),c=l.contributionBreakdown;const ledger=(label,amount)=>`<div class="ledger-line"><span>${esc(label)}</span><strong>${money(amount)}</strong></div>`;modal(`Computation · ${l.name}`,`<div class="row mb">${btn('Back to payroll','view-payroll','',dataAttrs(id))}${btn('Payslip','payslip','primary',dataAttrs(id)+` data-employee="${employee}"`)}</div><h3>Earnings</h3>${Object.entries(earningLabels).map(([k,v])=>ledger(v,l.earnings[k])).join('')}<div class="ledger-line total"><span>Gross compensation</span><strong>${money(l.gross)}</strong></div><h3 class="mt">Attendance detail</h3><p class="muted mb">${l.regularHours.toFixed(2)} regular hours · ${l.overtimeHours.toFixed(2)} overtime hours. Base wages appear once; premiums and night differential are added separately.</p>${table(['DATE / CLASSIFICATION','HOURS','HOURLY RATE','MULTIPLIER','PAY','NIGHT ADDITION'],l.details.map(d=>`<tr><td>${esc(d.date)}<small class="sub">${esc(d.label)}</small></td><td>${(d.minutes/60).toFixed(2)}</td><td>${money(d.hourlyRate||l.employee.hourlyRate)}</td><td>× ${d.multiplier}</td><td>${money(d.amount)}</td><td>${money(d.nightAmount||0)}</td></tr>`))}<h3 class="mt">Monthly contribution allocation</h3>${c?`<p class="muted mt">Strategy: ${esc(c.strategy)} · scheduled payroll ${c.index} of ${c.periods}. ${c.provisional?'Provisional; month-end true-up is required.':'Final scheduled allocation based on month-to-date compensation.'}</p>`:''}${Object.entries(contributionLabels).map(([k,v])=>ledger(v,l.contributions[k])).join('')}${c?`<details class="mt"><summary>View monthly targets and prior deductions</summary>${table(['COMPONENT','MONTH TARGET','ALREADY ALLOCATED','THIS RUN'],contributionKeys.map(k=>`<tr><td>${esc(contributionLabels[k])}</td><td>${money(c.target[k])}</td><td>${money(c.previous[k])}</td><td>${money(l.contributions[k])}</td></tr>`))}<p class="mt">This run = round(monthly target × ${c.fraction}) − prior deductions. SSS MSC: ${money(c.target.details.sss.msc)}. PhilHealth salary base: ${money(c.target.details.philhealth.base)}. Pag-IBIG base: ${money(c.target.details.pagibig.base)}.</p></details>`:''}<h3 class="mt">Withholding tax</h3>${ledger('Taxable compensation',l.taxable)}${l.taxBreakdown?`<p class="mt">${money(l.taxBreakdown.bracket.baseTax)} base tax + (${money(l.taxBreakdown.taxable)} − ${money(l.taxBreakdown.bracket.excessOver)}) × ${(l.taxBreakdown.bracket.percentage*100).toFixed(0)}% = <b>${money(l.tax)}</b>.</p>`:ledger('Tax adjustment',l.tax)}${ledger('Loans / advances',l.loan)}${ledger('Other deductions',l.otherDeductions)}<div class="ledger-line total"><span>Net pay</span><strong>${money(l.net)}</strong></div>`)}
