'derive-rates':()=>{const f=el('employee-form'),v=Object.fromEntries(new FormData(f));let daily=0;if(v.payrollType==='Monthly')daily=Number(v.monthlyBasic)*12/Number(v.monthlyDivisor);else if(v.payrollType==='Weekly')daily=Number(v.weeklyRate)/Number(v.normalDays);else if(v.payrollType==='Hourly')daily=Number(v.hourlyRate)*Number(v.normalHours);else daily=Number(v.dailyRate);if(!Number.isFinite(daily)||daily<=0)throw Error('Enter a positive salary and divisor.');f.elements.dailyRate.value=daily.toFixed(2);f.elements.hourlyRate.value=(daily/Number(v.normalHours)).toFixed(2);if(v.payrollType==='Monthly')f.elements.weeklyRate.value=(Number(v.monthlyBasic)*12/52).toFixed(2);toast('Rates derived. Review your employment policy before saving.')},
